<?php
namespace App\Livewire\Admin\Users;use App\Models\Permission;use App\Models\PermissionGroup;use App\Models\User;use App\Services\AccessControlService;use Illuminate\Support\Facades\Hash;use Livewire\Component;
class Create extends Component{public string $name='';public string $email='';public string $role='marketing';public bool $is_manager=false;public string $password='';public array $group_ids=[];public array $permission_ids=[];public function mount():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->isHR()||auth()->user()->hasPermission('users.create'),403);}public function save(AccessControlService $access){$actor=auth()->user();$roles=Index::roles();if(!$actor->isAdmin())unset($roles['admin']);$d=$this->validate(['name'=>['required','string','max:255'],'email'=>['required','email','max:255','unique:users,email'],'role'=>['required','in:'.implode(',',array_keys($roles))],'is_manager'=>['boolean'],'password'=>['required','string','min:8'],'group_ids'=>['array'],'group_ids.*'=>['integer','exists:permission_groups,id'],'permission_ids'=>['array'],'permission_ids.*'=>['integer','exists:permissions,id']]);if(!in_array($d['role'],['sales','call_center','operation','account','hr'],true))$d['is_manager']=false;$user=User::create(collect($d)->only(['name','email','role','is_manager'])->all()+['password'=>Hash::make($d['password'])]);if($actor->isAdmin())$access->sync($user,$d['group_ids'],$d['permission_ids'],$actor->id);session()->flash('success','User created.');return $this->redirectRoute('admin.users.edit',$user,navigate:true);}public function render(){return view('livewire.admin.users.form',['heading'=>'New user','submitLabel'=>'Create user','roles'=>$this->availableRoles(),'groups'=>PermissionGroup::orderBy('display_name')->get(),'permissions'=>Permission::orderBy('resource')->orderBy('action')->get(),'editing'=>false])->layout('components.layouts.admin',['title'=>'New user']);}private function availableRoles(){return auth()->user()->isAdmin()?Index::roles():collect(Index::roles())->except('admin')->all();}}
